def gen(rng):
    def fmt(ws, tgt, s):
        return str(len(ws)) + '\n' + ' '.join(ws) + '\n' + tgt + '\n' + str(s)
    tests = [fmt(['a'], 'a', 0), fmt(['a'], 'b', 0), fmt(['a', 'b'], 'b', 1), fmt(['x', 'y', 'z'], 'y', 0),
             fmt(['p', 'q', 'p', 'q'], 'q', 0), fmt(['k'] * 6, 'k', 3)]
    for n in (2, 3, 4, 5, 7, 10, 15, 25):
        for _ in range(3):
            alpha = ['a', 'b', 'c', 'd', 'e'] if n > 3 else ['a', 'b']
            ws = [rng.choice(alpha) for _ in range(n)]
            tests.append(fmt(ws, rng.choice(alpha + ['z']), rng.randrange(n)))
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def rw():
        return ''.join(rng.choice(letters) for _ in range(10))
    n = 100000
    ws = [rw() for _ in range(n)]
    tests.append(fmt(ws, ws[n // 2], 0))
    tests.append(fmt(ws, ws[n - 1], n // 2 - 3))
    tests.append(fmt(ws, 'zzzzzzzzzz', 12345))
    ws2 = [rng.choice(['ab', 'cd', 'ef']) for _ in range(n)]
    ws2[n // 3] = 'zz'
    tests.append(fmt(ws2, 'zz', 2 * n // 3))
    return tests
